  # Renders an inline Heroicons/Iconify SVG. `name` must be a key of ICONS.
  def icon(name, css_class: "size-5")
    path = ICONS.fetch(name)
    content_tag(:svg, path.html_safe,
      xmlns: "http://www.w3.org/2000/svg",
      fill: "none",
      viewbox: "0 0 24 24",
      "stroke-width": "1.5",
      stroke: "currentColor",
      class: css_class,
      "aria-hidden": "true")
  end
